mapper.select:
SELECT
m.id,
m.order_no AS orderNo,
m.schedule_time AS scheduleTime,
m.material_code AS materialCode,
m.material_desc AS materialDesc,
m.workshop,
m.quantity,
m.completed_quantity AS completedQuantity,
m.stock,
m.transfer_order AS transferOrder,
m.component_order AS componentOrder,
m.component_code AS componentCode,
m.component_desc AS componentDesc,
m.component_workshop AS componentWorkshop,
m.basic_start_date AS basicStartDate,
m.required_quantity AS requiredQuantity,
m.purchase_material AS purchaseMaterial,
m.purchase_material_desc AS purchaseMaterialDesc,
m.size_dimension AS sizeDimension,
m.purchase_required_qty AS purchaseRequiredQty,
m.delivered_quantity AS deliveredQuantity,
m.to_deliver_quantity AS toDeliverQuantity,
m.kit_qty AS kitQty,
m.kit_qty_single AS kitQtySingle,
m.purchase_order AS purchaseOrder,
m.line_number AS lineNumber,
m.order_date AS orderDate,
m.required_delivery_date AS requiredDeliveryDate,
m.actual_arrival_date AS actualArrivalDate,
m.supplier_name AS supplierName,
m.open_order_quantity AS openOrderQuantity,
m.allocated_required_qty AS allocatedRequiredQty,
m.remain_required_qty AS remainRequiredQty,
-- 使用 XMLAGG 替代 LISTAGG（Oracle 10g 兼容）
RTRIM(
XMLAGG(
XMLELEMENT(e, f.feedback_remark || '; ')
ORDER BY f.create_time
).EXTRACT('//text()'),
'; '
) AS feedbackRemarks
FROM aps_matching_result m
LEFT JOIN aps_purchase_feedback f
ON f.order_no = m.order_no
AND f.schedule_time = m.schedule_time
AND f.purchase_material = m.purchase_material
AND f.deleted = 0
AND f.tenant_id = 1   -- 若有多租户，添加此条件（可根据项目调整）
WHERE m.deleted = 0
AND m.tenant_id = 1


    AND m.order_no IN

        #{orderNo}



    AND m.material_code = #{reqVO.materialCode}


    AND m.material_desc = #{reqVO.materialDesc}


    AND m.workshop = #{reqVO.workshop}



    AND m.quantity = #{reqVO.quantity}


    AND m.completed_quantity = #{reqVO.completedQuantity}


    AND m.stock = #{reqVO.stock}


    AND m.transfer_order = #{reqVO.transferOrder}


    AND m.component_order = #{reqVO.componentOrder}


    AND m.component_code = #{reqVO.componentCode}


    AND m.component_desc = #{reqVO.componentDesc}


    AND m.component_workshop = #{reqVO.componentWorkshop}


    AND m.required_quantity = #{reqVO.requiredQuantity}


    AND m.unfinished_quantity = #{reqVO.unfinishedQuantity}


    AND m.purchase_material = #{reqVO.purchaseMaterial}


    AND m.purchase_material_desc = #{reqVO.purchaseMaterialDesc}


    AND m.purchase_required_qty = #{reqVO.purchaseRequiredQty}


    AND m.delivered_quantity = #{reqVO.deliveredQuantity}


    AND m.to_deliver_quantity = #{reqVO.toDeliverQuantity}


    AND m.kit_qty_single = #{reqVO.kitQtySingle}


    AND m.purchase_order = #{reqVO.purchaseOrder}


    AND m.line_number = #{reqVO.lineNumber}


    AND m.size_dimension = #{reqVO.sizeDimension}


    AND m.supplier_name LIKE CONCAT('%', #{reqVO.supplierName}, '%')


    AND m.open_order_quantity = #{reqVO.openOrderQuantity}




        AND m.schedule_time >= #{reqVO.scheduleTime[0]}


        AND m.schedule_time <= #{reqVO.scheduleTime[1]}




        AND m.basic_start_date >= #{reqVO.basicStartDate[0]}


        AND m.basic_start_date <= #{reqVO.basicStartDate[1]}




        AND m.order_date >= #{reqVO.orderDate[0]}


        AND m.order_date <= #{reqVO.orderDate[1]}




        AND m.required_delivery_date >= #{reqVO.requiredDeliveryDate[0]}


        AND m.required_delivery_date <= #{reqVO.requiredDeliveryDate[1]}




        AND m.actual_arrival_date >= #{reqVO.actualArrivalDate[0]}


        AND m.actual_arrival_date <= #{reqVO.actualArrivalDate[1]}





        AND m.create_time >= #{reqVO.createTime[0]}


        AND m.create_time <= #{reqVO.createTime[1]}



GROUP BY
m.id, m.order_no, m.schedule_time, m.material_code, m.material_desc,
m.workshop, m.quantity, m.completed_quantity, m.stock, m.transfer_order,
m.component_order, m.component_code, m.component_desc, m.component_workshop,
m.basic_start_date, m.required_quantity, m.purchase_material,
m.purchase_material_desc, m.size_dimension, m.purchase_required_qty,
m.delivered_quantity, m.to_deliver_quantity, m.kit_qty, m.kit_qty_single,
m.purchase_order, m.line_number, m.order_date, m.required_delivery_date,
m.actual_arrival_date, m.supplier_name, m.open_order_quantity , m.allocated_required_qty, m.remain_required_qty
ORDER BY m.schedule_time ASC, m.workshop ASC, m.order_no ASC
